import java.net.*;
import java.util.*;
import javax.swing.*;

final class WorkspaceState {
    static String preferences(VulnApp app){AdvancedTools a=app.advanced;Map<String,Object> p=new LinkedHashMap<>();p.put("port",app.port.getValue());p.put("attackDelay",a.attackDelay.getValue());p.put("attackLimit",a.attackLimit.getValue());p.put("concurrency",a.concurrency.getValue());p.put("urlEncode",a.urlEncode.isSelected());p.put("pages",a.pages.getValue());p.put("scanDelay",a.scanDelay.getValue());p.put("passive",a.passive.isSelected());p.put("active",a.active.isSelected());p.put("tokenRegex",a.tokenRegex.getText());p.put("tokenSamples",a.tokenSamples.getValue());p.put("wsUrl",a.wsUrl.getText());p.put("wsMessage",a.wsMessage.getText());p.put("payloadPipeline",a.payloadPipeline.getText());p.put("grep",a.grep.getText());p.put("extract",a.extract.getText());p.put("customChecks",app.workspace.customChecks.getText());p.put("browserUrl",app.workspace.browserUrl.getText());p.put("dynamicCrawl",app.workspace.dynamicCrawl.isSelected());p.put("instrumentDom",app.workspace.instrumentDom.isSelected());p.put("callbackBind",app.workspace.callbackBind.getText());p.put("callbackPublic",app.workspace.callbackPublic.getText());p.put("callbackHttp",app.workspace.callbackHttp.getValue());p.put("callbackDns",app.workspace.callbackDns.getValue());p.put("interceptRegex",app.workspace.interceptRegex.getText());p.put("interceptOnlyMatching",app.workspace.policy.interceptOnlyMatching);return Json.write(p);}
    static void spinner(JSpinner spinner,Object value){if(value instanceof Number n){SpinnerNumberModel model=(SpinnerNumberModel)spinner.getModel();int min=((Number)model.getMinimum()).intValue(),max=((Number)model.getMaximum()).intValue();spinner.setValue(Math.max(min,Math.min(max,n.intValue())));}}
    static void restore(VulnApp app,String text){Map<String,Object> p=Json.object(Json.parse(text));AdvancedTools a=app.advanced;Map<String,JSpinner> spinners=Map.ofEntries(Map.entry("port",app.port),Map.entry("attackDelay",a.attackDelay),Map.entry("attackLimit",a.attackLimit),Map.entry("concurrency",a.concurrency),Map.entry("pages",a.pages),Map.entry("scanDelay",a.scanDelay),Map.entry("tokenSamples",a.tokenSamples),Map.entry("callbackHttp",app.workspace.callbackHttp),Map.entry("callbackDns",app.workspace.callbackDns));spinners.forEach((key,spinner)->spinner(spinner,p.get(key)));a.urlEncode.setSelected(Boolean.TRUE.equals(p.get("urlEncode")));a.passive.setSelected(!Boolean.FALSE.equals(p.get("passive")));a.active.setSelected(Boolean.TRUE.equals(p.get("active")));a.tokenRegex.setText(Objects.toString(p.get("tokenRegex"),a.tokenRegex.getText()));a.wsUrl.setText(Objects.toString(p.get("wsUrl"),a.wsUrl.getText()));a.wsMessage.setText(Objects.toString(p.get("wsMessage"),""));a.payloadPipeline.setText(Objects.toString(p.get("payloadPipeline"),""));a.grep.setText(Objects.toString(p.get("grep"),""));a.extract.setText(Objects.toString(p.get("extract"),""));WorkspaceTools w=app.workspace;w.customChecks.setText(Objects.toString(p.get("customChecks"),""));w.compiledChecks=ScannerChecks.compile(w.customChecks.getText());w.browserUrl.setText(Objects.toString(p.get("browserUrl"),w.browserUrl.getText()));w.dynamicCrawl.setSelected(Boolean.TRUE.equals(p.get("dynamicCrawl")));w.instrumentDom.setSelected(Boolean.TRUE.equals(p.get("instrumentDom")));w.callbackBind.setText(Objects.toString(p.get("callbackBind"),"127.0.0.1"));w.callbackPublic.setText(Objects.toString(p.get("callbackPublic"),"http://127.0.0.1"));w.interceptRegex.setText(Objects.toString(p.get("interceptRegex"),".*"));w.policy.interceptPattern=java.util.regex.Pattern.compile(w.interceptRegex.getText(),java.util.regex.Pattern.DOTALL);w.policy.interceptOnlyMatching=Boolean.TRUE.equals(p.get("interceptOnlyMatching"));}
    static String sessions(NetworkPolicy policy){List<Object> macros=new ArrayList<>();policy.macros.forEach((key,m)->macros.add(Map.of("origin",m.origin().toString(),"request",m.request(),"regex",m.tokenRegex(),"header",m.targetHeader())));return Json.write(Map.of("headers",policy.sessionHeaders,"macros",macros));}
    static void sessions(NetworkPolicy policy,String text){Map<String,Object> saved=Json.object(Json.parse(text));policy.sessionHeaders.clear();Json.object(saved.get("headers")).forEach((key,value)->{URI uri=URI.create(key);String h=value.toString();int colon=h.indexOf(':');if(colon<1)throw new IllegalArgumentException("Invalid session header");NetworkPolicy.header(WorkbenchCore.get(uri),h.substring(0,colon),h.substring(colon+1).strip());policy.sessionHeaders.put(NetworkPolicy.origin(uri),h);});policy.macros.clear();for(Object item:(List<?>)saved.get("macros")){Map<String,Object> m=Json.object(item);URI uri=VulnApp.Packet.checked(URI.create(m.get("origin").toString()));policy.macros.put(NetworkPolicy.origin(uri),new NetworkPolicy.Macro(uri,m.get("request").toString(),m.get("regex").toString(),m.get("header").toString()));}}
}
